-- GL-17 option C: inv.sql is generated by run.sh from the live_* functions (security invoker copies).
-- GL-17 options, measured on the same data as measure*.sql (local only, nothing kept).
\set ON_ERROR_STOP 1
\ir measure_fn.sql
\ir inv.sql
grant execute on function pg_temp.inv_project_health(uuid), pg_temp.inv_programme_health(uuid), pg_temp.inv_portfolio_health(uuid) to authenticated;
select count(*) as tenants from public.organisations \gset
\echo tenants=:tenants
select id as t1 from public.organisations where slug = 'perf-test-university-t1' \gset
-- Option C: the same three reads, run as a member of t1 through RLS (what a refresh would cost
-- if it ran with that organisation's member's claims instead of as postgres).
select pg_temp.t('C: as t1 member, project rows', format('select sum(length(t::text)) from pg_temp.inv_project_health(%L) t', :'t1'), 3, 'authenticated', 'b1700000-0000-4000-8000-000000000001');
select pg_temp.t('C: as t1 member, programme rows', format('select sum(length(t::text)) from pg_temp.inv_programme_health(%L) t', :'t1'), 3, 'authenticated', 'b1700000-0000-4000-8000-000000000001');
select pg_temp.t('C: as t1 member, portfolio rows', format('select sum(length(t::text)) from pg_temp.inv_portfolio_health(%L) t', :'t1'), 3, 'authenticated', 'b1700000-0000-4000-8000-000000000001');
